package cn.haiduo;
import cn.haiduo.ai.AiModels;
import cn.haiduo.ai.AiConfiguration;
import com.sun.net.httpserver.HttpServer;
import java.net.*;
import java.nio.charset.StandardCharsets;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import org.springframework.mock.env.MockEnvironment;
class ModelAdapterTest {
 @Test void modelDeadlineIsBounded(){var chat=org.mockito.Mockito.mock(org.springframework.ai.chat.model.ChatModel.class);org.mockito.Mockito.when(chat.call(org.mockito.ArgumentMatchers.anyString())).thenAnswer(call->{Thread.sleep(30000);return "late";});org.springframework.beans.factory.ObjectProvider<org.springframework.ai.chat.model.ChatModel> chats=org.mockito.Mockito.mock(org.springframework.beans.factory.ObjectProvider.class);org.springframework.beans.factory.ObjectProvider<org.springframework.ai.embedding.EmbeddingModel> embeddings=org.mockito.Mockito.mock(org.springframework.beans.factory.ObjectProvider.class);org.mockito.Mockito.when(chats.getIfAvailable()).thenReturn(chat);org.mockito.Mockito.when(chats.getObject()).thenReturn(chat);org.mockito.Mockito.when(embeddings.getIfAvailable()).thenReturn(org.mockito.Mockito.mock(org.springframework.ai.embedding.EmbeddingModel.class));var models=new AiModels(chats,embeddings,new org.springframework.mock.env.MockEnvironment());assertTimeoutPreemptively(java.time.Duration.ofSeconds(18),()->assertThrows(org.springframework.web.server.ResponseStatusException.class,()->models.chat("deadline")));}
 @Test void configuredSpringAiModelsUseMockHttp()throws Exception{var server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.createContext("/v1/chat/completions",e->{e.getRequestBody().readAllBytes();byte[] body="{\"id\":\"mock\",\"object\":\"chat.completion\",\"created\":1,\"model\":\"mock-chat\",\"choices\":[{\"index\":0,\"message\":{\"role\":\"assistant\",\"content\":\"mock draft\"},\"finish_reason\":\"stop\"}],\"usage\":{\"prompt_tokens\":1,\"completion_tokens\":2,\"total_tokens\":3}}".getBytes(StandardCharsets.UTF_8);e.getResponseHeaders().add("Content-Type","application/json");e.sendResponseHeaders(200,body.length);e.getResponseBody().write(body);e.close();});server.createContext("/v1/embeddings",e->{e.getRequestBody().readAllBytes();byte[] body="{\"object\":\"list\",\"data\":[{\"object\":\"embedding\",\"index\":0,\"embedding\":[1.0,0.0]}],\"model\":\"mock-embedding\",\"usage\":{\"prompt_tokens\":1,\"total_tokens\":1}}".getBytes(StandardCharsets.UTF_8);e.getResponseHeaders().add("Content-Type","application/json");e.sendResponseHeaders(200,body.length);e.getResponseBody().write(body);e.close();});server.start();try{var env=new MockEnvironment().withProperty("AI_BASE_URL","http://127.0.0.1:"+server.getAddress().getPort()).withProperty("AI_API_KEY","mock-not-real").withProperty("AI_CHAT_MODEL","mock-chat").withProperty("AI_EMBEDDING_MODEL","mock-embedding");var c=new AiConfiguration();var api=c.modelApi(env);assertEquals("mock draft",c.chatModel(api,env).call("draft"));assertArrayEquals(new float[]{1,0},c.embeddingModel(api,env).embed("knowledge"));}finally{server.stop(0);}}
}
